using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
namespace BF4Launcher;
public static class ExternalLibraryTests {
 public static void Run(Action<bool,string> check) {
  string root=Path.Combine(Path.GetTempPath(),"BF4-ExternalLibrary-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"engine","builtin-mods"));
  var template=new ModManifest{Id="alpha",Name="alpha",Version="1",Fields=new(){new FieldDef{Id="value",Label="倍率",Type="number",Min=1,Max=10,DefaultValue=JsonValue.Create(1)}}};
  using(var z=ZipFile.Open(Path.Combine(root,"engine","builtin-mods","obsolete.zip"),ZipArchiveMode.Create))using(var w=new StreamWriter(z.CreateEntry("mod.json").Open()))w.Write(JsonSerializer.Serialize(template,Repository.Json));
  Repository.Atomic(Path.Combine(root,"engine","builtin-mod-catalog.json"),"{\"formatVersion\":1,\"mods\":[]}");
  var repo=new Repository(root);repo.Load();check(repo.ModCards.Count==0&&!Directory.Exists(Path.Combine(root,"mods")),"external-library-exe-only-does-not-create-mods");check(repo.Config.Mods.Count==0,"external-library-ignores-old-embedded-package-directory");
  void Install(string id,string version,int value) {var m=JsonSerializer.Deserialize<ModManifest>(JsonSerializer.Serialize(template,Repository.Json),Repository.Json)!;m.Id=id;m.Name=id;m.Version=version;var d=Path.Combine(root,"mods",id,version);Directory.CreateDirectory(d);Repository.Atomic(Path.Combine(d,"mod.json"),JsonSerializer.Serialize(m,Repository.Json));Repository.Atomic(Path.Combine(d,"config.json"),"{\"value\":"+value+",\"unknown\":42}");}
  Install("alpha","1",3);Install("alpha","2",5);Install("beta","1",7);Repository.Atomic(Path.Combine(root,"mods","catalog.json"),"{\"formatVersion\":1,\"defaultVersions\":{\"alpha\":\"2\",\"beta\":\"1\"}}");repo.RefreshModDirectory();check(repo.ModCards.Single(m=>m.Manifest.Id=="alpha").Version=="2","external-library-manual-refresh-uses-external-default");repo=new Repository(root);repo.Load();check(repo.ModCards.Count==2&&repo.Config.Mods.Count==3,"external-library-discovers-unpacked-version-directories");check(repo.ModCards.Single(m=>m.Manifest.Id=="alpha").Version=="2","external-library-initial-version-comes-from-external-catalog");check(repo.ModCards.All(m=>!m.Enabled),"external-library-new-mods-remain-disabled");
  repo.SelectModVersion("alpha","1");repo.SetModEnabled("alpha",true);var alpha=repo.ModCards.Single(m=>m.Manifest.Id=="alpha");alpha.Config["value"]=JsonValue.Create(6);repo.SaveModVersion(alpha);string config=Path.Combine(root,alpha.Directory,"config.json"),bytes=File.ReadAllText(config);repo=new Repository(root);repo.Load();check(repo.ModCards.Single(m=>m.Manifest.Id=="alpha").Version=="1"&&repo.ModCards.Single(m=>m.Manifest.Id=="alpha").Enabled,"external-library-restart-keeps-selected-version-and-switch");check(File.ReadAllText(config)==bytes,"external-library-restart-keeps-version-parameters-byte-identical");
  repo.RemoveModVersion(repo.Config.Mods.Single(m=>m.Key=="alpha@2"));repo=new Repository(root);repo.Load();check(!Directory.Exists(Path.Combine(root,"mods","alpha","2")),"external-library-uninstalled-version-is-not-restored");repo.RemoveModGroup("beta");repo=new Repository(root);repo.Load();check(!repo.ModCards.Any(m=>m.Manifest.Id=="beta"),"external-library-removed-mod-is-not-restored");
  string mods=Path.GetFullPath(Path.Combine(root,"mods")),detached=Path.GetFullPath(Path.Combine(root,"detached-mods"));if(!mods.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!detached.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("测试目录不正确");Directory.Move(mods,detached);repo=new Repository(root);repo.Load();check(!Directory.Exists(mods),"external-library-missing-folder-not-recreated-with-existing-config");check(repo.ModCards.Count==0&&repo.Config.Mods.All(m=>!m.Enabled),"external-library-missing-files-hidden-and-disabled");check(repo.Config.Mods.Single(m=>m.Key=="alpha@1").Config["value"]!.GetValue<int>()==6,"external-library-missing-files-keep-cached-parameters");Directory.Move(detached,mods);repo=new Repository(root);repo.Load();check(repo.ModCards.Count==1&&!repo.ModCards[0].Enabled,"external-library-restored-files-discovered-without-auto-enable");check(File.ReadAllText(config)==bytes,"external-library-restored-config-not-overwritten");
  using var payload=Assembly.GetExecutingAssembly().GetManifestResourceStream("BF4Launcher.EnginePayload")!;using var archive=new ZipArchive(payload,ZipArchiveMode.Read);check(!archive.Entries.Any(e=>e.FullName.StartsWith("mods/",StringComparison.OrdinalIgnoreCase)||e.FullName.StartsWith("engine/builtin-mods/",StringComparison.OrdinalIgnoreCase)||e.FullName=="engine/builtin-mod-catalog.json"),"external-library-engine-payload-has-no-mod-packages");
 }
}
